challenge.solution:
const launch = document.querySelector("#launch");
const status = document.querySelector("#status");

function updateLaunch() {
  // data-fuel'i oku, sayıya çevir, düğmeyi ve #status'u güncelle
  const fuel = Number(launch.getAttribute("data-fuel"));
  if (fuel >= 50) {
    launch.removeAttribute("disabled");
    status.textContent = `Kalkışa hazır (yakıt ${fuel})`;
  } else {
    launch.setAttribute("disabled", "");
    status.textContent = `Yakıt yetersiz (yakıt ${fuel})`;
  }
}

updateLaunch();

// #docs bağlantısının href niteliğini değiştir
document.querySelector("#docs").setAttribute("href", "https://developer.mozilla.org");

check.js:
assert($("#launch").disabled === false, "Yakıt 80 iken #launch düğmesi etkin olmalı (disabled kaldırılmalı).");
assert($("#status").textContent.trim() === "Kalkışa hazır (yakıt 80)", "#status 'Kalkışa hazır (yakıt 80)' olmalı.");
assert($("#docs").getAttribute("href") === "https://developer.mozilla.org", "#docs bağlantısının href'i 'https://developer.mozilla.org' olmalı.");
$("#launch").setAttribute("data-fuel", "30");
updateLaunch();
assert($("#launch").disabled === true, "Yakıt 30 iken updateLaunch() düğmeyi devre dışı bırakmalı.");
assert($("#status").textContent.trim() === "Yakıt yetersiz (yakıt 30)", "Yakıt 30 iken #status 'Yakıt yetersiz (yakıt 30)' olmalı; yakıtı nitelikten oku.");

