const game = { title: "Yıldız Avcısı", pilot: "Ada", level: 1 };

function showStart(g) {
  // elemanları bul ve g'deki bilgilerle doldur
  document.querySelector("#game-title").textContent = g.title;
  document.querySelector("#pilot").textContent = g.pilot;
  document.querySelector("#level").textContent = g.level;
  document.querySelector("#start-btn").classList.add("ready");
}

showStart(game);

check.js:
assert($("#game-title").textContent.trim() === "Yıldız Avcısı", "#game-title 'Yıldız Avcısı' olmalı.");
assert($("#pilot").textContent.trim() === "Ada" && $("#level").textContent.trim() === "1", "#pilot 'Ada', #level '1' olmalı.");
assert($("#start-btn").classList.contains("ready"), "#start-btn düğmesine ready sınıfı eklenmeli.");
showStart({ title: "Test Uçuşu", pilot: "Can", level: 4 });
assert($("#game-title").textContent.trim() === "Test Uçuşu" && $("#pilot").textContent.trim() === "Can" && $("#level").textContent.trim() === "4", "showStart, verilen g nesnesindeki bilgileri yazmalı; metinleri elle yazma.");

