project_task.solution:
const question = { text: "Kızıl gezegen hangisi?", options: ["Mars", "Venüs", "Merkür"], answer: 0 };

function showQuestion(q) {
  // #question ve .option düğmeleri
  document.querySelector("#question").textContent = q.text;
  const buttons = document.querySelectorAll(".option");
  buttons.forEach((btn, i) => {
    btn.textContent = q.options[i];
  });
}

showQuestion(question);

check.js:
const texts = () => $$(".option").map((b) => b.textContent.trim()).join("|");
assert($("#question").textContent.trim() === "Kızıl gezegen hangisi?", "#question 'Kızıl gezegen hangisi?' olmalı.");
assert(texts() === "Mars|Venüs|Merkür", "Düğmelerde sırasıyla Mars, Venüs, Merkür yazmalı.");
showQuestion({ text: "En büyük gezegen?", options: ["Satürn", "Jüpiter", "Neptün"], answer: 1 });
assert($("#question").textContent.trim() === "En büyük gezegen?" && texts() === "Satürn|Jüpiter|Neptün", "showQuestion verilen q nesnesini göstermeli; metinleri elle yazma.");
